// Regenerate the offline catalog after editing the authoritative JSON files.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const read = file => JSON.parse(fs.readFileSync(path.join(root, file), 'utf8'));
fs.writeFileSync(path.join(root, 'js/data/text-original.js'),
  '// Generated by tools/sync-text-original.js; edit locales/*.json instead.\n' +
  'G.TextOriginal = ' + JSON.stringify(read('locales/zh.json')) + ';\n' +
  'G.TextAliases = ' + JSON.stringify(read('locales/aliases.json')) + ';\n');
